    // "tablewareStatus": 0,
    // "orderDishes": "string"
    // }
  ]
  private diaForm = []
  private isSearch: boolean = false
  private orderStatus = 2 //列表字段展示所需订单状态,用于分页请求数据
  private dialogOrderStatus = 0 //弹窗所需订单状态，用于详情展示字段
  private cancelOrderReasonList = [
    {
      value: 1,
      label: '订单量较多，暂时无法接单',
